using System;using System.Text;using UnityEngine;using LWS.TruckSports;using LWS.TruckBowling;
namespace LWS.TruckLimbo {
public enum LimboPhase {CountIn,Attempt,RoundResult,Complete}
public sealed class LimboMatch:SportsEventSession {
 public LimboReview review;float replayClock;public override bool ReplayControls=>review!=null&&review.Active;public override void ExtraAction(string key)=>review?.Action(key);
 public LimboRacer[] racers;public SportsRallyViews views;public SportsChaosWeather atmosphere;public SportsWeatherPresets weatherPresets;public AudioSource partyMusic;
 public readonly LimboRules rules=new LimboRules();public LimboPhase Phase{get;private set;}public float Age{get;private set;}public int PhysicalClears{get;private set;}public int PhysicalHits{get;private set;}public float startHeight=3,heightStep=.18f;public int maximumRounds=9;
 readonly bool[] airborne=new bool[8];readonly Vector3[] anchors=new Vector3[8];readonly float[] aiNoise=new float[8];readonly StringBuilder labels=new StringBuilder();int seed,focus;
 public override bool SupportsSplitAIViews=>true;public override bool ParticipantLocked(int slot)=>rules.done[slot];
 public override string Title=>"TRUCK LIMBO";public override int MinimumPlayers=>1;public override int MaximumPlayers=>8;public override int OptionCount=>6;public override string OptionLabel=>(option<3?"ELIMINATION":"BEST HEIGHT")+" · "+new[]{"EASY","NORMAL","HARD"}[option%3];public override bool MultiViewHUD=>views!=null&&views.Humans>0&&(review==null||!review.Active);
 public override string Help=>"HOW LOW CAN SIX TONS GO?\nDrive with your assigned movement controls. Reverse brakes first. Hold ACTION to lower the real NWH suspension; release to recover. Left/right gently steer AND lean the actual truck body. Compression and lean change the real body pose, not a decorative fake cab. Time your crouch near the bar: holding it for more than 2.5 seconds gradually exhausts the pressure reserve.\n\nClear the ENTIRE truck under a physical limbo pole. Touching or displacing it fails the attempt; going around, jumping over, or escaping the course does not count. Each course resolves independently. A generous 35-second limit resolves a genuine stalled attempt as a failure. Pause and reconnect preserve every truck and bar.\n\nELIMINATION: failed trucks leave after the round. Survivors face a lower bar until one remains. Everyone failing together compares best cleared height, then points; exact ties share victory. SOLO continues until failure or the ninth height. BEST HEIGHT keeps everyone for five increasingly low rounds.\n\n100 points per clear, +25 for each lower round, +25 for less than 12cm roof clearance, +25 for a controlled 12–65 degree lean below 4.5m/s. These are visible physical outcomes. Lowest cleared height ranks first. All AI uses the same controls, suspension and solid bar contacts. Four local humans maximum; AI fills up to eight. Optional AI cameras affect presentation only. Offline party physics.";
 public override string Header=>Title+" · BAR "+rules.Height.ToString("F2")+" m · ROUND "+rules.Round+" · "+atmosphere.Description;
 public override string Status=>review!=null&&review.Active?"RECORDED FINAL BAR · "+review.motion.Speed.ToString("F2")+"× · CAMERA "+(review.motion.Angle+1):Phase==LimboPhase.CountIn?"READY · "+Mathf.Max(1,Mathf.CeilToInt(3-Age)):Phase==LimboPhase.RoundResult?"BAR RESULTS LOCKED":Phase==LimboPhase.Complete?"PARTY CHAMPIONS":"DRIVE · HOLD ACTION TO SQUAT · LEAN WITH LEFT/RIGHT";
 public override string Standings{get{labels.Clear();for(int i=0;i<setup.count;i++)labels.Append(setup.players[i].name).Append("  ").Append(rules.points[i]).Append(" PTS · ").Append(float.IsInfinity(rules.best[i])?"NO CLEAR":rules.best[i].ToString("F2")+"m").Append(i+1==setup.count?"":"\n");return labels.ToString();}}
 public int ResultPlace(int slot)=>rules.ResultPlace(slot);
 public override string Results{get{labels.Clear();for(int i=0;i<setup.count;i++)if(rules.winners[i])labels.Append(setup.players[i].name).Append("  ");return labels.ToString()+"WIN THE LIMBO PARTY!\n\n"+Standings;}}
 public override bool ValidateSources(out string reason){if(!base.ValidateSources(out reason))return false;int humans=0;for(int i=0;i<setup.count;i++)if(setup.players[i].source!=BowlingSource.AI)humans++;if(humans>4){reason="At most four local humans; AI can fill eight separate courses.";return false;}return true;}
 public override bool TryReadScoreCard(int card,out string value,out string detail){value=rules.points[card].ToString();detail=(float.IsInfinity(rules.best[card])?"NO CLEAR":rules.best[card].ToString("F2")+" m BEST")+" · "+racers[card].Phase.ToString().ToUpperInvariant();return true;}
 protected override void BeginGame(){seed=UnityEngine.Random.Range(1,1000000);PhysicalClears=PhysicalHits=0;float step=heightStep*(option%3==0?.8f:option%3==2?1.2f:1);rules.Start(setup.count,option<3?LimboFormat.Elimination:LimboFormat.BestHeight,startHeight,step,option<3?maximumRounds:5);atmosphere.ConfigurePreset(weatherPresets.Resolve(seed),seed);var rng=new System.Random(seed);for(int i=0;i<setup.count;i++)aiNoise[i]=((float)rng.NextDouble()-.5f)*2;BeginRound();}
 void BeginRound(){Age=0;Phase=LimboPhase.CountIn;for(int i=0;i<racers.Length;i++){racers[i].gameObject.SetActive(i<setup.count);racers[i].bar.gameObject.SetActive(i<setup.count);if(i<setup.count)racers[i].Prepare(rules.active[i],rules.Height);}views.Restore();replayClock=0;review?.ResetRecord();Gate();}
 Vector2 AI(int i,out bool crouch){var r=racers[i];float skill=(int)setup.players[i].difficulty;float distance=r.bar.Plane-r.truck.body.position.z;float reach=Mathf.Lerp(3.5f,6.2f,skill*.5f)+aiNoise[i];crouch=distance<reach&&distance> -4;float needed=Mathf.InverseLerp(startHeight-.15f,startHeight-1.1f,rules.Height);float lean=Mathf.Clamp(needed*(.65f+skill*.15f)+aiNoise[i]*(.18f-skill*.05f),-.9f,.9f);if(i%2==0)lean=-lean;var heading=r.truck.body.rotation*Vector3.forward;var target=new Vector3(r.laneCenter-r.truck.body.position.x,0,Mathf.Max(3,distance+2));float align=Mathf.Clamp(Vector3.SignedAngle(heading,target,Vector3.up)/18,-1,1);float targetSpeed=Mathf.Lerp(3.8f,2.6f,skill*.5f);float speed=Vector3.Dot(r.truck.body.linearVelocity,Vector3.forward);float throttle=speed>targetSpeed?-.15f:.7f;return new Vector2(Mathf.Clamp(align+(distance<5?lean*.32f:0),-1,1),throttle);}
 protected override void Simulate(float dt){Age+=dt;replayClock+=dt;review?.Record(replayClock);atmosphere.Tick(Time.time);if(Phase==LimboPhase.CountIn){foreach(var r in racers)if(r.gameObject.activeSelf)r.Hold();if(Age>=3){foreach(var r in racers)if(r.gameObject.activeSelf)r.Release();Age=0;Phase=LimboPhase.Attempt;feedback.Play(5,0,true);}return;}if(Phase==LimboPhase.RoundResult){if(Age<2.5f)return;if(!rules.NextRound()){Phase=LimboPhase.Complete;EndMatch();}else BeginRound();return;}if(Phase!=LimboPhase.Attempt)return;for(int i=0;i<setup.count;i++){bool crouch;Vector2 drive;if(setup.players[i].source==BowlingSource.AI)drive=AI(i,out crouch);else{drive=commands[i];crouch=ActionHeld(i)&&setup.players[i].released;}racers[i].Step(drive,crouch,dt);if(racers[i].Phase==LimboAttempt.Approach)focus=i;}if(rules.RoundComplete){Phase=LimboPhase.RoundResult;Age=0;feedback.Play(4,0,true);}}
 public void Record(int slot,bool success,bool close,bool style){int prior=slot>=0&&slot<rules.Count?rules.points[slot]:0;if(!rules.ResolveAttempt(slot,success,close,style))return;int earned=rules.points[slot]-prior;if(earned>0)ConfirmScore("bar:"+rules.Round+":"+slot,slot,earned,rules.points[slot],"BAR CLEARED",SportsScoreTier.Major);if(success)PhysicalClears++;else if(racers[slot].HitBar)PhysicalHits++;feedback.Play(success?5:3,0,true);Pulse(slot,success?.12f:.24f,.1f);}
 public override string ViewText(int v){int i=views.owners[v];var r=racers[i];return setup.players[i].name+" · "+rules.points[i]+" PTS\nBAR "+rules.Height.ToString("F2")+"m · ROUND "+rules.Round+"\n"+r.Reaction+" · SQUAT "+Mathf.RoundToInt(r.Compression*100)+"%";}
 protected override void Present(float dt){if(racers==null||views==null)return;if(review!=null&&review.Active){review.Tick(dt);return;}for(int i=0;i<setup.count;i++){anchors[i]=racers[i].truck.body.position;airborne[i]=!racers[i].truck.Grounded;}views.Focus=focus;views.Follow(dt,airborne,anchors);for(int v=0;v<views.Humans;v++)if(Running&&!rules.active[views.owners[v]])views.views[v].Pose(anchors[focus]+Vector3.up,new Vector3(10,7,-12),65);if(partyMusic!=null){partyMusic.volume=Live?settings.music*.35f:0;if(Live&&!partyMusic.isPlaying)partyMusic.Play();}}
 protected override void SetPaused(bool pause){atmosphere?.Pause(pause);if(partyMusic!=null){if(pause)partyMusic.Pause();else if(Running)partyMusic.UnPause();}}
 protected override void StopGame(){review?.Stop(false);if(racers!=null)foreach(var r in racers)if(r!=null&&r.bar!=null){if(!r.bar.body.isKinematic)r.bar.body.linearVelocity=r.bar.body.angularVelocity=Vector3.zero;r.bar.body.isKinematic=true;}if(partyMusic!=null)partyMusic.Stop();if(racers!=null)foreach(var r in racers)if(r!=null)r.Restore();}
 protected override void StopSounds(){if(racers!=null)foreach(var r in racers)r.truck.StopSound();}
}
}
